// Re-age post_weight on ATTRIBUTED rows only, ternary author model, 50-row batches (own execution).
const helpers=this.helpers;
const KEY='<REDACTED_SUPABASE_JWT>';
const BASE='https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const H={apikey:KEY,Authorization:'Bearer '+KEY};
const ctx=$('Build Context').first().json;const cfg=(ctx&&ctx.config)?ctx.config:{};
const clamp=cfg.sentimentClamp||{min:0.5,max:1.3};
const ewAll=cfg.engagementWeights||{};
const lw=ewAll.LinkedIn||{reaction:1,comment:3,reshare:10,image:1.5};
const xw=ewAll.X||{like:1,reply:2,repost:10,quote:4};
const rw=ewAll.Reddit||{upvote:1,comment:3};
const AB=cfg.authorBaseline||{company:1.0,employee:2.0,external:5.0};
const AEM=cfg.authorEngMult||{company:1.0,employee:1.2,external:2.0};
const hl=cfg.halfLifeDays||{};
const hlLI=hl.LinkedIn||14,hlX=hl.X||7,hlReddit=hl.Reddit||10,hlNews=hl['Google News']||30;
const urnSet=new Set((ctx&&ctx.companies?ctx.companies:[]).map(c=>String(c.linkedin_urn||'')).filter(Boolean));
const EMP={};
try{const aff=await helpers.httpRequest({method:'GET',url:BASE+'/author_affiliation?select=profile_id,competitor&verdict=eq.employee',headers:H,json:true});for(const a of (aff||[])){if(a&&a.profile_id&&a.competitor)EMP[String(a.competitor).trim().toLowerCase()+'|'+String(a.profile_id)]=true;}}catch(e){}
function num(x,d){return (x!=null?Number(x):d);}
function round6(x){return parseFloat(Number(x).toFixed(6));}
function sentMult(x){if(x==null)return 1.0;const s=Math.max(-3,Math.min(3,Number(x)));return clamp.min+((s+3)/6)*(clamp.max-clamp.min);}
function ageDays(t){if(!t)return 0;const d=new Date(t);return isNaN(d)?0:Math.max(0,(Date.now()-d.getTime())/86400000);}
function decay(age,hlife){return age<=7?1:Math.pow(2,-age/hlife);}
function reachOf(eng){return Math.pow(Math.max(0,eng),49/50);}
function newsTierMult(u){const nt=cfg.newsTiers;if(!nt||!nt.tiers)return 1;const m=String(u||'').match(/^[a-z][a-z0-9+.-]*:\/\/([^\/?#]+)/i);let host=m?m[1].replace(/^www\./i,'').toLowerCase():'';if(!host)return (nt.default!=null?nt.default:1);for(const k in nt.tiers){const t=nt.tiers[k];const ds=(t&&t.domains)||[];for(let i=0;i<ds.length;i++){const d=ds[i];if(host===d||host.endsWith('.'+d))return t.mult;}}return (nt.default!=null?nt.default:1);}
function authorTier(r){const a=(r.author&&typeof r.author==='object')?r.author:{};const prof=String(a.profile_id||'');const head=String(a.headline||'').toLowerCase();const cn=String(r.companyName||'');if(prof&&urnSet.has(prof))return 'company';if(prof&&cn&&cn!=='NONE'&&EMP[cn.toLowerCase()+'|'+prof])return 'employee';if(cn&&cn!=='NONE'&&head.indexOf(cn.toLowerCase())!==-1)return 'employee';return 'external';}
function tierB(t){return t==='company'?num(AB.company,1.0):(t==='employee'?num(AB.employee,2.0):num(AB.external,5.0));}
function tierM(t){return t==='company'?num(AEM.company,1.0):(t==='employee'?num(AEM.employee,1.2):num(AEM.external,2.0));}
const ATTR='&companyName=not.is.null&companyName=neq.NONE';
async function process(table,cols,orderCol,keyCol,computeRow,mode){const BATCH=50;let off=0,total=0;const hh=Object.assign({},H,{'Content-Type':'application/json','Prefer':(mode==='patch'?'return=minimal':'resolution=merge-duplicates,return=minimal')});for(;;){const url=BASE+'/'+table+'?select='+cols+ATTR+'&order='+orderCol+'&limit='+BATCH+'&offset='+off;const batch=await helpers.httpRequest({method:'GET',url,headers:H,json:true});const arr=Array.isArray(batch)?batch:[];if(!arr.length)break;const rows=arr.map(computeRow);if(mode==='patch'){for(const r of rows){const u=BASE+'/'+table+'?'+keyCol+'=eq.'+encodeURIComponent(r[keyCol]);const body={};for(const k in r){if(k!==keyCol)body[k]=r[k];}try{await helpers.httpRequest({method:'PATCH',url:u,headers:hh,body,json:true});total++;}catch(e){}}}else{try{await helpers.httpRequest({method:'POST',url:BASE+'/'+table+'?on_conflict='+keyCol,headers:hh,body:rows,json:true});total+=rows.length;}catch(e){}}if(arr.length<BATCH)break;off+=BATCH;}return total;}
const liN=await process('linkedin_posts','activity_id,companyName,totalReactions,comments,reshares,imageURL,sentiment,posted_at,author','activity_id','activity_id',function(r){let eng=num(lw.reaction,1)*Number(r.totalReactions||0)+num(lw.comment,3)*Number(r.comments||0)+num(lw.reshare,10)*Number(r.reshares||0);if(r.imageURL&&String(r.imageURL).length>0)eng+=num(lw.image,1.5);const reach=reachOf(eng);const t=authorTier(r);return {activity_id:r.activity_id,post_weight:round6((tierB(t)+reach*tierM(t))*sentMult(r.sentiment)*decay(ageDays(r.posted_at),hlLI))};},'upsert');
const twN=await process('tweets','id,companyName,likeCount,replyCount,retweetCount,quoteCount,authorWeight,sentiment,createdAt','id','id',function(r){const eng=num(xw.like,1)*Number(r.likeCount||0)+num(xw.reply,2)*Number(r.replyCount||0)+num(xw.repost,10)*Number(r.retweetCount||0)+num(xw.quote,4)*Number(r.quoteCount||0);const reach=reachOf(eng);const own=Number(r.authorWeight||5)<=1;const B=own?num(AB.company,1.0):num(AB.external,5.0);const M=own?num(AEM.company,1.0):num(AEM.external,2.0);return {id:r.id,post_weight:round6((B+reach*M)*sentMult(r.sentiment)*decay(ageDays(r.createdAt),hlX))};},'upsert');
const gnN=await process('googlenews','url,companyName,sentiment,publishedAt','url','url',function(r){return {url:r.url,post_weight:round6(newsTierMult(r.url)*sentMult(r.sentiment)*decay(ageDays(r.publishedAt),hlNews))};},'upsert');
const rdN=await process('reddit_posts','id,companyName,score,numComments,sentiment,createdAt','id','id',function(r){const eng=num(rw.upvote,1)*Math.max(0,Number(r.score||0))+num(rw.comment,3)*Number(r.numComments||0);return {id:r.id,post_weight:round6(reachOf(eng)*sentMult(r.sentiment)*decay(ageDays(r.createdAt),hlReddit))};},'patch');
return [{json:{decayRefresh:true,model:'ternary; attributed-only; batch50',linkedin:liN,x:twN,news:gnN,reddit:rdN}}];
